<?php
namespace App\Http\Controllers;
use App\Services\{Identity,Notifications};
use App\Jobs\BuildExport;
use App\Support\Json;
use Illuminate\Http\Request;
use Illuminate\Support\Facades\{DB,Hash,Crypt,Storage,Mail};
use Illuminate\Support\Str;
final class AccountController extends Controller {
    public function __construct(private Identity $identity,private Notifications $notifications){}
    private function user(Request $r): object{return $r->attributes->get('player');}
    public function profile(Request $r){$u=$this->user($r);$d=$r->validate(['name'=>['sometimes','string','min:2','max:40','regex:/^[\p{Arabic}A-Za-z0-9 _-]+$/u'],'avatar'=>'sometimes|in:explorer_boy_blue,explorer_boy_glasses,explorer_elder_scout,explorer_elder_turquoise,explorer_girl_orange,explorer_girl_purple,explorer_man_orange,explorer_woman_yellow','visibility'=>'sometimes|in:public,private','locale'=>'sometimes|in:ar,en','timezone'=>'sometimes|timezone:all','preferred_world'=>'sometimes|exists:worlds,id','preferences'=>'sometimes|array:push,sound,music,personalized_ads','preferences.push'=>'sometimes|boolean','preferences.sound'=>'sometimes|boolean','preferences.music'=>'sometimes|boolean','preferences.personalized_ads'=>'sometimes|boolean']);if(isset($d['preferences']))$d['preferences']=Json::encode(array_merge(Json::read($u->preferences),$d['preferences']));DB::table('users')->where('id',$u->id)->update($d+['updated_at'=>now()]);if(isset($d['timezone']))$this->notifications->reschedule($u->id,$d['timezone']);return response()->json($this->identity->profile($u->id));}
    public function consent(Request $r){$d=$r->validate(['document_version'=>'required|string|max:100','choices'=>'required|array:personalized_ads,notifications,terms_accepted','choices.personalized_ads'=>'required|boolean','choices.notifications'=>'required|boolean','choices.terms_accepted'=>'sometimes|boolean']);$u=$this->user($r);DB::table('consents')->insert(['user_id'=>$u->id,'document_version'=>$d['document_version'],'choices'=>Json::encode($d['choices']),'created_at'=>now()]);$preferences=Json::read($u->preferences);$preferences['push']=$d['choices']['notifications'];$preferences['personalized_ads']=$d['choices']['personalized_ads'];DB::table('users')->where('id',$u->id)->update(['preferences'=>Json::encode($preferences),'updated_at'=>now()]);return response()->json(['saved'=>true,'choices'=>$d['choices']]);}
    public function devices(Request $r){$u=$this->user($r);return response()->json(['devices'=>DB::table('api_tokens')->where('user_id',$u->id)->where('expires_at','>',now())->get(['id','device_name','platform','last_activity_at','expires_at'])->map(fn($t)=>(array)$t+['is_current'=>$t->id===$r->attributes->get('player_token')->id])]);}
    public function revoke(Request $r){$this->identity->recent($r->attributes->get('player_token'));$d=$r->validate(['token_id'=>'nullable|uuid','others'=>'sometimes|boolean','confirm'=>'required|accepted']);$q=DB::table('api_tokens')->where('user_id',$this->user($r)->id);if($d['others']??false)$q->where('id','!=',$r->attributes->get('player_token')->id);elseif(!empty($d['token_id']))$q->where('id',$d['token_id']);else Json::fail('choose_device');$ids=$q->pluck('id');DB::table('push_devices')->whereIn('api_token_id',$ids)->update(['active'=>false]);$q->delete();return response()->json(['revoked'=>$ids->count()]);}
    public function emailRequest(Request $r){$u=$this->user($r);$this->identity->eligible($u);$this->identity->recent($r->attributes->get('player_token'));$d=$r->validate(['new_email'=>'required|email:rfc|max:254']);if($u->is_guest)Json::fail('registration_required',403);$email=strtolower($d['new_email']);if(DB::table('users')->where('email',$email)->exists())Json::fail('email_unavailable',409);return response()->json($this->identity->issueOtp($email,'email_change',$u->id));}
    public function emailConfirm(Request $r){$d=$r->validate(['challenge_id'=>'required|uuid','code'=>'required|string|max:12']);$u=$this->user($r);$this->identity->recent($r->attributes->get('player_token'));$c=$this->identity->consumeOtp($d['challenge_id'],$d['code'],'email_change');if($c->user_id!==$u->id)Json::fail('invalid_code',401);DB::transaction(function()use($u,$c){DB::table('users')->where('id',$u->id)->lockForUpdate()->first();if(DB::table('users')->where('email',$c->email)->where('id','!=',$u->id)->exists())Json::fail('email_unavailable',409);DB::table('users')->where('id',$u->id)->update(['email'=>$c->email,'email_verified_at'=>now(),'updated_at'=>now()]);$this->notifications->securityAlert($u->id,$c->id);});foreach(array_unique([$u->email,$c->email])as$email){try{Mail::raw('Your PuzzleQuest email address was changed. Contact info@50sols.com if this was not you.',fn($m)=>$m->to($email)->subject('PuzzleQuest security notice'));}catch(\Throwable $e){/* Inbox remains canonical; no sensitive mail payload is logged. */}}return response()->json(['email_changed'=>true]);}
    public function export(Request $r){$u=$this->user($r);if($u->is_guest)Json::fail('registration_required',403);$this->identity->recent($r->attributes->get('player_token'));if(DB::table('exports')->where('user_id',$u->id)->whereIn('state',['queued','building'])->exists())Json::fail('export_already_pending',409);$id=(string)Str::uuid();DB::table('exports')->insert(['id'=>$id,'user_id'=>$u->id,'created_at'=>now(),'updated_at'=>now()]);BuildExport::dispatch($id)->afterCommit();return response()->json(['id'=>$id,'state'=>'queued'],202);}
    public function exports(Request $r){return response()->json(['exports'=>DB::table('exports')->where('user_id',$this->user($r)->id)->orderByDesc('created_at')->get(['id','state','expires_at','created_at'])]);}
    public function downloadExport(Request $r,string $id){$e=DB::table('exports')->where('id',$id)->where('user_id',$this->user($r)->id)->first();if(!$e||$e->state!=='ready'||!$e->expires_at||now()->gte($e->expires_at)||!Storage::disk('local')->exists($e->path))Json::fail('export_unavailable',404);return Storage::disk('local')->download($e->path,'PuzzleQuest-personal-data.zip',['Cache-Control'=>'no-store']);}
    public function delete(Request $r){$u=$this->user($r);$this->identity->recent($r->attributes->get('player_token'));$d=$r->validate(['confirmation'=>'required|in:DELETE','confirm'=>'required|accepted']);if(!config('puzzlequest.delete_enabled')||!config('puzzlequest.legal_approved'))Json::fail('deletion_policy_not_approved',503);if($u->is_guest)Json::fail('registration_required',403);DB::table('users')->where('id',$u->id)->update(['status'=>'deletion_pending','visibility'=>'private','recover_until'=>now()->addDays(30),'purge_after'=>now()->addDays(60),'updated_at'=>now()]);DB::table('api_tokens')->where('user_id',$u->id)->delete();DB::table('push_devices')->where('user_id',$u->id)->update(['active'=>false]);return response()->json(['deletion_requested'=>true,'recovery_deadline'=>now()->addDays(30)->toIso8601String(),'active_data_deleted_by'=>now()->addDays(60)->toIso8601String()]);}
    public function recoveryRequest(Request $r){$d=$r->validate(['email'=>'required|email:rfc|max:254']);return response()->json($this->identity->issueOtp($d['email'],'account_recovery'));}
    public function recoveryConfirm(Request $r){$d=$r->validate(['challenge_id'=>'required|uuid','code'=>'required|string|max:12']);$c=$this->identity->consumeOtp($d['challenge_id'],$d['code'],'account_recovery');$u=DB::table('users')->find($c->user_id);if(!$u||$u->status!=='deletion_pending'||!$u->recover_until||now()->gte($u->recover_until))Json::fail('recovery_unavailable',409);DB::table('users')->where('id',$u->id)->update(['status'=>'active','recover_until'=>null,'purge_after'=>null,'updated_at'=>now()]);return response()->json($this->identity->token($u->id,$r->only('device_name','device_id','platform')));}
    public function inbox(Request $r){$uid=$this->user($r)->id;$snapshot=(string)Str::uuid();$ids=DB::table('inbox')->where('user_id',$uid)->whereNull('read_at')->where('expires_at','>',now())->pluck('id');DB::table('inbox_snapshots')->insert(['id'=>$snapshot,'user_id'=>$uid,'message_ids'=>Json::encode($ids->all()),'expires_at'=>now()->addMinutes(15)]);return response()->json(['messages'=>DB::table('inbox')->where('user_id',$uid)->where('expires_at','>',now())->orderByDesc('created_at')->paginate(30),'read_all_snapshot_id'=>$snapshot]);}
    public function readInbox(Request $r){$d=$r->validate(['message_id'=>'required|uuid']);DB::table('inbox')->where('id',$d['message_id'])->where('user_id',$this->user($r)->id)->whereNull('read_at')->update(['read_at'=>now()]);return response()->json(['read'=>true]);}
    public function readAll(Request $r){$d=$r->validate(['snapshot_id'=>'required|uuid']);$snapshot=DB::table('inbox_snapshots')->where('id',$d['snapshot_id'])->where('user_id',$this->user($r)->id)->where('expires_at','>',now())->first();if(!$snapshot)Json::fail('inbox_snapshot_expired',409);$n=DB::table('inbox')->where('user_id',$this->user($r)->id)->whereIn('id',Json::read($snapshot->message_ids))->whereNull('read_at')->update(['read_at'=>now()]);return response()->json(['marked_read'=>$n]);}
    public function tickets(Request $r){return response()->json(DB::table('support_tickets')->where('user_id',$this->user($r)->id)->orderByDesc('created_at')->paginate(20,['id','category','title','state','created_at','updated_at']));}
    public function ticket(Request $r,string $id){$t=DB::table('support_tickets')->where('id',$id)->where('user_id',$this->user($r)->id)->first();abort_unless($t,404);unset($t->image_path);return response()->json(['ticket'=>$t,'replies'=>DB::table('support_replies')->where('ticket_id',$id)->orderBy('id')->get()]);}
    public function ticketImage(Request $r,string $id){$t=DB::table('support_tickets')->where('id',$id)->where('user_id',$this->user($r)->id)->first();abort_unless($t&&$t->image_path&&Storage::disk('local')->exists($t->image_path),404);return response()->file(Storage::disk('local')->path($t->image_path),['Cache-Control'=>'no-store']);}
    public function createTicket(Request $r){$d=$r->validate(['category'=>'required|in:account_login,gameplay_progress,rewards_points,ads,privacy_data,technical_issue,other','title'=>'required|string|min:3|max:150','description'=>'required|string|min:10|max:10000','reply_email'=>'nullable|email:rfc|max:254','image'=>'nullable|file|mimes:png,jpg,jpeg,webp|max:2048']);$id=(string)Str::uuid();$path=$r->file('image')?->store('support','local');DB::table('support_tickets')->insert(['id'=>$id,'user_id'=>$this->user($r)->id,'category'=>$d['category'],'title'=>$d['title'],'description'=>$d['description'],'reply_email'=>empty($d['reply_email'])?null:strtolower($d['reply_email']),'image_path'=>$path,'created_at'=>now(),'updated_at'=>now()]);\App\Jobs\NotifySupport::dispatch($id)->afterCommit();return response()->json(['id'=>$id,'state'=>'open'],201);}
    public function replyTicket(Request $r,string $id){$d=$r->validate(['body'=>'required|string|min:1|max:10000']);$t=DB::table('support_tickets')->where('id',$id)->where('user_id',$this->user($r)->id)->first();abort_unless($t,404);if($t->state==='closed')Json::fail('ticket_closed',409);DB::table('support_replies')->insert(['ticket_id'=>$id,'body'=>$d['body'],'created_at'=>now()]);DB::table('support_tickets')->where('id',$id)->update(['state'=>'open','updated_at'=>now()]);\App\Jobs\NotifySupport::dispatch($id)->afterCommit();return response()->json(['reply_saved'=>true]);}
    public function pushDevice(Request $r){$d=$r->validate(['token'=>'required|string|min:20|max:4096','platform'=>'required|in:android,ios','permission'=>'required|boolean']);$uid=$this->user($r)->id;$hash=hash('sha256',$d['token']);$existing=DB::table('push_devices')->where('token_hash',$hash)->lockForUpdate()->first();DB::table('push_devices')->where('api_token_id',$r->attributes->get('player_token')->id)->where('token_hash','!=',$hash)->update(['active'=>false]);$values=['user_id'=>$uid,'api_token_id'=>$r->attributes->get('player_token')->id,'token'=>Crypt::encryptString($d['token']),'platform'=>$d['platform'],'permission'=>$d['permission'],'active'=>true,'updated_at'=>now()];if($existing)DB::table('push_devices')->where('id',$existing->id)->update($values);else DB::table('push_devices')->insert($values+['id'=>(string)Str::uuid(),'token_hash'=>$hash,'created_at'=>now()]);return response()->json(['registered'=>true,'effective_permission'=>$d['permission']]);}
}
